			m = end(t, traceHops(t, m, 1))
			footer := m.footer.Text()

			m = feed(t, m, typed...)

			if got := m.pathModel.input.Value(); got != traceLevelHost {
				t.Errorf("hidden field = %q, want %q untouched", got, traceLevelHost)
